import { llmsIndex } from "@/lib/discovery";
import { textResponse } from "@/lib/text-response";

export const dynamic = "force-dynamic";

export function GET() {
  return textResponse(llmsIndex(), "/llms.txt", "text/plain; charset=utf-8");
}

import { createMcpRoute } from "@vercel/geistdocs/routes/mcp";
import { config } from "@/lib/geistdocs/config";
import { GET as search } from "../search/route";

const handler = createMcpRoute({ config, search });

export { handler as GET, handler as POST };

import { setTimeout } from "node:timers/promises";
import { describe, expect, test } from "vitest";
import { components, crawl } from "./crawl.js";
import type { FetchNode } from "./github.js";
import type { Edge, GraphNode, NodeKey } from "./types.js";

/** Build an offline FetchNode from a fixture of key -> outgoing edge targets. */
function fakeFetch(graph: Record<NodeKey, Array<Partial<Edge> & { to: NodeKey }>>): FetchNode {
  return async (owner, repo, number, depth) => {
    const key = `${owner}/${repo}#${number}`;
    const edges: Edge[] = (graph[key] ?? []).map((e) => ({ via: "text", ...e }));
    return {
      key,
      owner,
      repo,
      number,
      kind: "Issue",
      title: key,
      state: "OPEN",
      url: `https://github.com/${owner}/${repo}/issues/${number}`,
      depth,
      edges,
      externalLinks: [],
      fetched: true,
    } satisfies GraphNode;
  };
}

const opts = (over: Partial<Parameters<typeof crawl>[1]> = {}) => ({
  maxDepth: 2,
  maxNodes: 80,
  hubThreshold: 12,
  concurrency: 4,
  primaryRepo: { owner: "o", repo: "r" },
  ...over,
});

describe("crawl", () => {
  test("follows edges and dedupes cycles", async () => {
    const fetch = fakeFetch({
      "o/r#1": [{ to: "o/r#2" }],
      "o/r#2": [{ to: "o/r#1" }], // cycle back
    });
    const { nodes } = await crawl([{ owner: "o", repo: "r", number: 1 }], opts(), fetch);
    expect([...nodes.keys()].sort()).toEqual(["o/r#1", "o/r#2"]);
  });

  test("respects the node cap and records what it dropped", async () => {
    const fetch = fakeFetch({
      "o/r#1": [{ to: "o/r#2" }, { to: "o/r#3" }],
    });
    const { nodes, cappedOut } = await crawl(
      [{ owner: "o", repo: "r", number: 1 }],
      opts({ maxNodes: 2 }),
      fetch,
    );
    expect(nodes.size).toBe(2);
    expect(cappedOut.size).toBeGreaterThan(0);
  });

  test("hub guard fetches but does not expand a high-degree node", async () => {
    const hubEdges = Array.from({ length: 5 }, (_, i) => ({ to: `o/r#${100 + i}` }));
    const fetch = fakeFetch({ "o/r#1": [{ to: "o/r#2" }], "o/r#2": hubEdges });
    const { nodes } = await crawl(
      [{ owner: "o", repo: "r", number: 1 }],
      opts({ hubThreshold: 3 }),
      fetch,
    );
    expect(nodes.get("o/r#2")?.hub).toBe(true);
    // hub's targets were never enqueued
    expect(nodes.has("o/r#100")).toBe(false);
  });

  test("fetches cross-repo refs one hop but does not expand them", async () => {
    const fetch = fakeFetch({
      "o/r#1": [{ to: "other/x#9" }],
      "other/x#9": [{ to: "other/x#10" }],
    });
    const { nodes } = await crawl([{ owner: "o", repo: "r", number: 1 }], opts(), fetch);
    expect(nodes.has("other/x#9")).toBe(true); // fetched
    expect(nodes.has("other/x#10")).toBe(false); // not expanded
  });

  test("bounds node requests in flight", async () => {
    let active = 0;
    let peak = 0;
    const fetch: FetchNode = async (owner, repo, number, depth) => {
      active++;
      peak = Math.max(peak, active);
      await setTimeout(5);
      active--;
      return {
        key: `${owner}/${repo}#${number}`,
        owner,
        repo,
        number,
        kind: "Issue",
        title: String(number),
        state: "OPEN",
        url: "",
        depth,
        edges: [],
        externalLinks: [],
        fetched: true,
      };
    };
    await crawl(
      Array.from({ length: 9 }, (_, index) => ({ owner: "o", repo: "r", number: index + 1 })),
      opts({ concurrency: 3 }),
      fetch,
    );
    expect(peak).toBe(3);
  });
});

describe("components", () => {
  test("groups connected nodes and separates disjoint ones", async () => {
    const fetch = fakeFetch({
      "o/r#1": [{ to: "o/r#2" }],
      "o/r#2": [],
      "o/r#9": [],
    });
    const { nodes } = await crawl(
      [
        { owner: "o", repo: "r", number: 1 },
        { owner: "o", repo: "r", number: 9 },
      ],
      opts(),
      fetch,
    );
    const comps = components(nodes);
    expect(comps.length).toBe(2);
    expect(comps[0].length).toBe(2); // {#1,#2} largest first
  });
});

import { createSearchRoute } from "@vercel/geistdocs/routes/search";
import { config } from "@/lib/geistdocs/config";
import { geistdocsSource } from "@/lib/geistdocs/source";

export const GET = createSearchRoute({ config, source: geistdocsSource });

import { generateNotFoundMarkdown } from "@vercel/agent-readability";
import { docsPath, isSafePathSegments } from "@/lib/docs-paths";
import { geistdocsSource } from "@/lib/geistdocs/source";
import { siteUrl } from "@/lib/site";
import { textResponse } from "@/lib/text-response";

export const dynamic = "force-dynamic";

export async function GET(_request: Request, { params }: { params: Promise<{ slug?: string[] }> }) {
  const { slug = [] } = await params;
  const safe = isSafePathSegments(slug);
  const page = safe ? geistdocsSource.source.getPage(slug, "en") : undefined;
  if (!page) {
    return textResponse(
      generateNotFoundMarkdown(safe ? docsPath(slug) : "/docs/not-found", {
        baseUrl: siteUrl,
        sitemapUrl: "/sitemap.md",
        indexUrl: "/llms.txt",
        exampleUrl: "/docs/get-started",
      }),
      null,
      "text/markdown; charset=utf-8",
      404,
    );
  }
  return textResponse(await geistdocsSource.getPageMarkdown(page), docsPath(page.slugs));
}

import type { Model } from "./html.js";

export function parseModel(value: unknown): Model {
  if (!value || typeof value !== "object") throw new Error("expected a dashboard model");
  const m = value as Model;
  if (
    !m.provider ||
    typeof m.provider.id !== "string" ||
    !m.provider.id ||
    typeof m.provider.name !== "string" ||
    typeof m.provider.logo !== "string" ||
    typeof m.provider.repoUrl !== "string" ||
    !Array.isArray(m.provider.signals) ||
    typeof m.repo !== "string" ||
    !m.repo ||
    (m.id !== undefined && (typeof m.id !== "string" || !m.id)) ||
    !m.nodes ||
    typeof m.nodes !== "object" ||
    Array.isArray(m.nodes) ||
    !Array.isArray(m.groups) ||
    !Array.isArray(m.cleanup) ||
    !Array.isArray(m.seeds) ||
    !m.stats
  )
    throw new Error("invalid dashboard model");
  const unsafeKey = (key: string) =>
    ["__proto__", "prototype", "constructor", "toString", "valueOf"].includes(key);
  const safeUrl = (url: unknown) =>
    typeof url === "string" && (!url || /^https?:\/\/[^\s]+$/i.test(url));
  const strings = (value: unknown): value is string[] =>
    Array.isArray(value) && value.every((v) => typeof v === "string");
  if (
    m.provider.signals.some(
      (s) =>
        !s ||
        typeof s.id !== "string" ||
        typeof s.label !== "string" ||
        !["warn", "danger"].includes(s.tone),
    ) ||
    (m.provider.views !== undefined &&
      (!strings(m.provider.views) ||
        !m.provider.views.length ||
        m.provider.views.some((v) => !["explore", "impact", "swarm", "rank"].includes(v)))) ||
    (m.provider.metrics !== undefined &&
      (!strings(m.provider.metrics) ||
        m.provider.metrics.some((v) => !["heat", "links", "blast", "depth"].includes(v)))) ||
    (m.provider.filters !== undefined &&
      (!strings(m.provider.filters) ||
        m.provider.filters.some((v) => !["solution", "review"].includes(v)))) ||
    m.cleanup.some((c) => !c || typeof c.text !== "string") ||
    (m.label !== undefined && typeof m.label !== "string") ||
    (m.coverage &&
      (!strings(m.coverage.messages) ||
        (m.coverage.warnings !== undefined && !strings(m.coverage.warnings))))
  )
    throw new Error("invalid dashboard metadata");
  if (!safeUrl(m.provider.repoUrl) || (m.url !== undefined && !safeUrl(m.url)))
    throw new Error("dashboard links must use HTTP or HTTPS");
  if (
    /<\s*[^>]*\b(?:on[\w-]+|href|src|style)\s*=|<\s*[!?]|&(?:#|colon)/i.test(m.provider.logo) ||
    [...m.provider.logo.matchAll(/<\s*\/?\s*([\w:-]+)/g)].some(
      (match) =>
        !["svg", "g", "path", "circle", "ellipse", "rect", "line", "polyline", "polygon"].includes(
          match[1],
        ),
    )
  )
    throw new Error("provider logo must contain static SVG shapes");
  for (const [key, n] of Object.entries(m.nodes)) {
    if (
      unsafeKey(key) ||
      !n ||
      n.key !== key ||
      typeof n.title !== "string" ||
      typeof n.state !== "string" ||
      typeof n.repo !== "string" ||
      !["Issue", "PullRequest", "Unknown"].includes(n.kind) ||
      !Number.isFinite(n.depth) ||
      !Array.isArray(n.out) ||
      !Array.isArray(n.in) ||
      !Array.isArray(n.overlaps) ||
      !strings(n.flags) ||
      !strings(n.mentionedBy) ||
      !Array.isArray(n.external)
    )
      throw new Error(`invalid captured item: ${key}`);
    if (
      [n.identifier, n.stateLabel, n.stateType, n.author, n.verdict, n.read?.error].some(
        (v) => v !== undefined && typeof v !== "string",
      )
    )
      throw new Error(`invalid captured text: ${key}`);
    if (
      n.pr &&
      (![n.pr.review, n.pr.mergeable, n.pr.updated].every((v) => typeof v === "string") ||
        ![n.pr.adds, n.pr.dels, n.pr.files].every(
          (v) => typeof v === "number" && Number.isFinite(v) && v >= 0,
        ))
    )
      throw new Error(`invalid pull request metadata: ${key}`);
    if (
      (n.attachments !== undefined && !Array.isArray(n.attachments)) ||
      (n.read &&
        (!Array.isArray(n.read.coverage) ||
          n.read.coverage.some(
            (c) =>
              !c || typeof c.source !== "string" || !Number.isSafeInteger(c.pages) || c.pages < 0,
          )))
    )
      throw new Error(`invalid read metadata: ${key}`);
    if (
      !safeUrl(n.url) ||
      n.external.some((url) => !safeUrl(url)) ||
      n.attachments?.some(
        (link) =>
          !link ||
          !safeUrl(link.url) ||
          (link.title !== undefined && typeof link.title !== "string"),
      )
    )
      throw new Error(`captured links must use HTTP or HTTPS: ${key}`);
    if (
      n.heat &&
      !["comments", "participants", "reactions", "daysOpen", "inboundRefs"].every((k) => {
        const v = n.heat?.[k as keyof NonNullable<typeof n.heat>];
        return typeof v === "number" && Number.isFinite(v) && v >= 0;
      })
    )
      throw new Error(`invalid heat signals: ${key}`);
    if (
      n.out.some(
        (e) => !e || typeof e.to !== "string" || unsafeKey(e.to) || typeof e.via !== "string",
      ) ||
      n.in.some(
        (e) => !e || typeof e.from !== "string" || unsafeKey(e.from) || typeof e.via !== "string",
      ) ||
      n.overlaps.some(
        (o) =>
          !o ||
          typeof o.with !== "string" ||
          unsafeKey(o.with) ||
          !Array.isArray(o.shared) ||
          !o.shared.every((f) => typeof f === "string") ||
          !Number.isInteger(o.significant) ||
          o.significant < 0,
      )
    )
      throw new Error(`invalid captured relationships: ${key}`);
  }
  for (const g of m.groups)
    if (
      !g ||
      typeof g.label !== "string" ||
      typeof g.subtitle !== "string" ||
      !Array.isArray(g.members) ||
      !g.members.every((k) => typeof k === "string" && Object.hasOwn(m.nodes, k))
    )
      throw new Error("invalid captured cluster");
  const count = (v: unknown) => typeof v === "number" && Number.isSafeInteger(v) && v >= 0;
  const optionalNumber = (v: unknown) =>
    v === null || (typeof v === "number" && Number.isFinite(v));
  if (
    m.sweep !== undefined &&
    (!Array.isArray(m.sweep) ||
      m.sweep.some(
        (g) =>
          !g ||
          !["competing", "stale", "overlap"].includes(g.kind) ||
          (g.next !== undefined && !["verify", "choose", "compare"].includes(g.next)) ||
          (g.issue !== null && (typeof g.issue !== "string" || unsafeKey(g.issue))) ||
          !strings(g.sharedFiles) ||
          !optionalNumber(g.overlapScore) ||
          !count(g.resolves) ||
          typeof g.allStale !== "boolean" ||
          !optionalNumber(g.smallestChange) ||
          typeof g.summary !== "string" ||
          !Array.isArray(g.pullRequests) ||
          g.pullRequests.some(
            (pr) =>
              !pr ||
              typeof pr.key !== "string" ||
              unsafeKey(pr.key) ||
              typeof pr.title !== "string" ||
              !safeUrl(pr.url) ||
              typeof pr.isDraft !== "boolean" ||
              typeof pr.mergeable !== "string" ||
              !count(pr.additions) ||
              !count(pr.deletions) ||
              (pr.staleBase !== null && typeof pr.staleBase !== "boolean") ||
              !strings(pr.missingOnBase),
          ),
      ))
  )
    throw new Error("invalid sweep groups");
  return m;
}

import { describe, expect, test } from "vitest";
import { buildReconcileReport, renderReconcile } from "./reconcile.js";
import type { GraphNode, NodeKey } from "./types.js";

function node(
  key: NodeKey,
  kind: "Issue" | "PullRequest",
  state: string,
  edges: GraphNode["edges"] = [],
): GraphNode {
  const [repoKey, rawNumber] = key.split("#");
  const [owner, repo] = repoKey.split("/");
  return {
    key,
    owner,
    repo,
    number: Number(rawNumber),
    kind,
    title: `${kind} ${rawNumber}`,
    state,
    url: `https://github.com/${repoKey}/issues/${rawNumber}`,
    depth: 0,
    edges,
    externalLinks: [],
    fetched: true,
  };
}

function report(values: GraphNode[]) {
  return buildReconcileReport(new Map(values.map((value) => [value.key, value])), {
    repo: "o/r",
    seeds: ["o/r#1"],
    seedLimit: 80,
    nodeCap: 80,
    cappedOut: [],
    generatedAt: "2026-08-14T00:00:00.000Z",
  });
}

describe("buildReconcileReport", () => {
  test("nominates an issue with merged closing work for behavioral verification", () => {
    const result = report([
      node("o/r#1", "Issue", "OPEN"),
      node("o/r#2", "PullRequest", "MERGED", [{ to: "o/r#1", via: "closes" }]),
    ]);
    expect(result.items[0]).toMatchObject({
      key: "o/r#1",
      action: "verify-completed",
      confidence: "medium",
      evidence: [
        {
          code: "merged-closing-work",
          related: ["o/r#2"],
        },
      ],
    });
    expect(result.nextSteps).toEqual([
      "Verify nominated actions against current main, acceptance criteria, and live behavior before changing GitHub state.",
    ]);
  });

  test("finds an open PR superseded by merged work on the same issue", () => {
    const result = report([
      node("o/r#1", "Issue", "CLOSED"),
      node("o/r#2", "PullRequest", "OPEN", [{ to: "o/r#1", via: "closes" }]),
      node("o/r#3", "PullRequest", "MERGED", [{ to: "o/r#1", via: "closes" }]),
    ]);
    expect(result.items[0]).toMatchObject({
      key: "o/r#2",
      action: "close-superseded",
      confidence: "high",
    });
  });

  test("finds possible supersession even when the open PR is a seed", () => {
    const issue = node("o/r#1", "Issue", "CLOSED", [{ to: "o/r#2", via: "cross-ref" }]);
    const open = node("o/r#2", "PullRequest", "OPEN");
    open.pr = {
      isDraft: false,
      reviewDecision: "",
      mergeable: "MERGEABLE",
      createdAt: "2026-01-01T00:00:00.000Z",
      mergedAt: "",
      updatedAt: "2026-01-01T00:00:00.000Z",
      additions: 1,
      deletions: 0,
      changedFiles: 1,
      files: ["src/a.ts"],
    };
    const merged = node("o/r#3", "PullRequest", "MERGED", [{ to: issue.key, via: "closes" }]);
    merged.pr = {
      ...open.pr,
      createdAt: "2026-01-02T00:00:00.000Z",
      mergedAt: "2026-01-03T00:00:00.000Z",
    };
    const result = report([issue, open, merged]);
    expect(result.items[0]).toMatchObject({
      key: "o/r#2",
      action: "verify-superseded",
      confidence: "medium",
    });
  });

  test("keeps unlinked issues explicit instead of declaring them stale", () => {
    const result = report([node("o/r#1", "Issue", "OPEN")]);
    expect(result.items[0]).toMatchObject({
      action: "keep-untracked",
      confidence: "high",
      evidence: [{ code: "no-related-pr", related: [] }],
    });
    expect(result.nextSteps).toEqual([
      "Reproduce or inspect untracked issues before prioritizing or closing them.",
    ]);
  });

  test("reports competing PRs and deterministic counts", () => {
    const issue = node("o/r#1", "Issue", "OPEN");
    const first = node("o/r#2", "PullRequest", "OPEN", [{ to: issue.key, via: "closes" }]);
    const second = node("o/r#3", "PullRequest", "OPEN", [{ to: issue.key, via: "closes" }]);
    first.flags = ["competes with o/r#3 to close o/r#1"];
    second.flags = ["competes with o/r#2 to close o/r#1"];
    const result = report([issue, first, second]);
    expect(result.counts.byAction["resolve-competing"]).toBe(3);
    expect(result.items.map((item) => item.key)).toEqual(["o/r#1", "o/r#2", "o/r#3"]);
    expect(result.items.map((item) => item.evidence[0])).toMatchObject([
      { code: "multiple-open-closing-prs", related: ["o/r#2", "o/r#3"] },
      { code: "competing-open-pr", related: ["o/r#1", "o/r#3"] },
      { code: "competing-open-pr", related: ["o/r#1", "o/r#2"] },
    ]);
  });

  test("reports node fetch failures as incomplete evidence", () => {
    const failed = node("o/r#1", "Issue", "FETCH_ERROR");
    failed.fetched = false;
    const result = report([failed]);
    expect(result.limits.fetchFailures).toEqual(["o/r#1"]);
    expect(result.counts.openIssues).toBe(0);
    expect(result.nextSteps).toEqual([
      "Retry failed graph nodes before acting on their absence from this report.",
    ]);
  });

  test("gives an empty backlog only the discovery next step", () => {
    const result = buildReconcileReport(new Map(), {
      repo: "o/r",
      seeds: [],
      seedLimit: 80,
      nodeCap: 80,
      cappedOut: [],
      generatedAt: "2026-08-14T00:00:00.000Z",
    });
    expect(result.items).toEqual([]);
    expect(result.nextSteps).toEqual([
      "Dogfood the product and inspect repository intent before proposing the next direction.",
    ]);
  });

  test("puts incomplete coverage before item-specific actions", () => {
    const result = buildReconcileReport(
      new Map([["o/r#1", node("o/r#1", "PullRequest", "OPEN")]]),
      {
        repo: "o/r",
        seeds: ["o/r#1"],
        seedLimit: 1,
        nodeCap: 1,
        cappedOut: ["o/r#2"],
        generatedAt: "2026-08-14T00:00:00.000Z",
      },
    );
    expect(result.nextSteps).toEqual([
      "Increase --max-nodes or re-seed omitted neighborhoods before claiming full backlog coverage.",
      "Run the repository review gate on every PR selected for merge.",
    ]);
  });
});

describe("renderReconcile", () => {
  test("renders limits and verification guardrails", () => {
    const result = report([node("o/r#1", "Issue", "OPEN")]);
    const markdown = renderReconcile(result);
